output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of the shopping trip, the shopper is obliged to take the available cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_shelf_pickup_without_cart",
    "text": "Items may only be picked up from shelves while the shopper is holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          {
            "not": "cart_possessed"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "The shopper is prohibited from carrying merchandise by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_taking_it",
    "text": "Once the shopper takes a cart, they are obliged to return it to the north-west cart return before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "cart_acquired": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "hasCart",
              "at_cart_return",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_acquired",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "The cart may be put down only at the designated cart return at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_designated_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "at_designated_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "The shopper is prohibited from exiting unless the cart has already been parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_returned_to_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_without_cart",
    "text": "The shopper must leave the store on foot rather than while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              "cart_possessed"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After the cart has been returned to the bay, the shopper must not retrieve the cart or interact with shelves again.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
